INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('f44c99b7-c235-f332-5d5a-fcd1c6f4bf1f', 'DeWalt DCD796D2 Brushless Zarbali Akkumulyatorli Shurupovyort 18V', 'dewalt-dcd796d2-zarbali-shurupovyort-18v', 'DeWalt DCD796D2 — eng so''nggi avlod cho''tkasiz (Brushless) motorli zarbali drel-shurupovyort. 70 Nm yuqori aylanma moment beton, g''isht, yog''och va metallga oson ishlov beradi. Komplektda 2 ta 2.0Ah XR Li-Ion batareya va keys mavjud.', 2650000, 2950000, 10, '2ec429c3-7a00-6278-0322-624bcd653654', 'DeWalt', 15, 'DW-DCD796D2', 5, 36, 'https://images.unsplash.com/photo-1572981779307-38b8cabb2407?q=80&w=800&auto=format&fit=crop', true, false, true, '{"Motor turi":"Cho''tkasiz (Brushless)","Akkumulyator":"2x 18V / 2.0 Ah Li-Ion","Maksimal moment":"70 Nm","Tezlik bosqichlari":"2 bosqich (0-550 / 0-2000 ayl/daq)","Patron":"1.5 - 13 mm (to''liq metall)","Zarb funksiyasi":"Mavjud (0-34000 zarb/daq)","Kafolat":"2 yil"}'::jsonb) ON CONFLICT (id) DO NOTHING;
