INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('ff054e7e-ca5b-7a7f-893d-ef578f6b891a', 'Makita DF333DWYE Akkumulyatorli Drel-Shurupovyort 12V', 'makita-df333dwye-shurupovyort-12v', 'Makita DF333DWYE — mebel yig''ish, gipsokarton o''rnatish va ta''mirlash ishlari uchun eng xaridorgir ixcham shurupovyort. Og''irligi atigi 1.1 kg. 2 ta batareya va tezkor zaryadlash stansiyasi bilan keladi.', 1350000, 1500000, 10, '2ec429c3-7a00-6278-0322-624bcd653654', 'Makita', 22, 'MKT-DF333', 4.9, 51, 'https://images.unsplash.com/photo-1580901368919-7738efb0f87e?q=80&w=800&auto=format&fit=crop', true, false, false, '{"Kuchlanish":"12V CXT","Akkumulyator":"2x 1.5 Ah Li-Ion","Maksimal moment":"30 Nm","Patron":"0.8 - 10 mm tez qisuvchi","LED yoritish":"Mavjud"}'::jsonb) ON CONFLICT (id) DO NOTHING;
