INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('c517b3c8-6771-ec69-52af-5a883068586d', 'Total TIDLI20012 Cho''tkasiz Zarbali Shurupovyort 20V', 'total-tidli20012-chotkasiz-zarbali-20v', 'Kuchli 20V Total shurupovyort Brushless motor va zarbli mexanizmga ega. Hamyonbop narxda yuqori sifat, 2 ta 2.0Ah akkumulyator, nasadkalar to''plami va sifatli sumka.', 980000, 1150000, 15, '2ec429c3-7a00-6278-0322-624bcd653654', 'Total', 28, 'TTL-TIDLI20', 4.7, 22, 'https://images.unsplash.com/photo-1572981779307-38b8cabb2407?q=80&w=800&auto=format&fit=crop', true, false, true, '{"Kuchlanish":"20V","Motor":"Cho''tkasiz (Brushless)","Moment":"45 Nm","Komplekt":"2 akkumulyator + sumka + aksessuarlar"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('2b9065d3-5d03-0789-c1a5-dd6e76ce1fd3', 'Bosch GBH 2-26 DRE Professional Perforator SDS-Plus', 'bosch-gbh-2-26-dre-professional-perforator', 'Bosch GBH 2-26 DRE — qurilish va burg''ulash sohasida dunyo standarti hisoblangan afsonaviy perforator. 800 Vt motor va 2.7 J zarb kuchi beton va toshni oson yoradi. 3 xil rejim: burg''ulash, zarba bilan burg''ulash, qazish (otboynik).', 1850000, 2100000, 12, 'e02986ab-8b78-f9cf-704e-b3796fcf12dc', 'Bosch', 14, 'BSH-GBH226', 5, 64, 'https://images.unsplash.com/photo-1586864387967-d02ef85d93e8?q=80&w=800&auto=format&fit=crop', true, false, false, '{"Quvvat":"800 Vt","Zarb energiyasi":"2.7 J","Patron":"SDS-Plus","Betonda burg''ulash":"26 mm gacha","Rejimlar":"3 rejim","Kafolat":"1 yil"}'::jsonb) ON CONFLICT (id) DO NOTHING;
