INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('1737da2e-4953-807e-8198-4f2600b0ac3d', 'DeWalt D25143K SDS-Plus Og''ir Zarbli Perforator 900W', 'dewalt-d25143k-zarbli-perforator', 'DeWalt D25143K — 900 Vt quvvatli motor va 3.2 Joul zarba energiyasi bilan o''z toifasidagi eng samarali perforator. Tebranishga qarshi AVC tizimi qo''ldagi charchoqni 50% gacha kamaytiradi.', 2300000, 2600000, 12, 'e02986ab-8b78-f9cf-704e-b3796fcf12dc', 'DeWalt', 9, 'DW-D25143K', 5, 18, 'https://images.unsplash.com/photo-1586864387967-d02ef85d93e8?q=80&w=800&auto=format&fit=crop', true, false, true, '{"Quvvat":"900 Vt","Zarb kuchi":"3.2 J","Patron":"SDS-Plus","Vibratsiyaga qarshi":"AVC tizimi"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('e3910df2-4bd7-78de-e97a-a2cf4fcb476f', 'Resanta SAI-220 Invertor Payvandlash Apparati', 'resanta-sai-220-invertor-svarka', 'Resanta SAI-220 — 140V dan 260V gacha bo''lgan pasaytirilgan kuchlanishda ham barqaror ishlaydigan eng mashhur svarka apparati. Hot Start, Arc Force va Anti-Stick funksiyalari payvandlashni yangi boshlovchilar uchun ham juda osonlashtiradi.', 1550000, 1750000, 11, 'bd8af332-35bc-e973-6f46-d355950a5027', 'Resanta', 20, 'RSN-SAI220', 4.9, 37, 'https://images.unsplash.com/photo-1617791160588-241658c0f566?q=80&w=800&auto=format&fit=crop', true, false, true, '{"Payvandlash toki":"10 - 220 A","Kirish kuchlanishi":"140 - 260 V","Elektrod diametri":"1.6 - 5.0 mm","Texnologiya":"IGBT Invertor","Og''irligi":"4.9 kg","Kafolat":"2 yil rasmiy"}'::jsonb) ON CONFLICT (id) DO NOTHING;
