INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('ed921b31-52f5-824f-c70f-99aa0b210ce9', 'Bosch GLM 50-27 CG Professional Yashil Lazer Ruletka', 'bosch-glm-50-27-cg-yashil-lazer-ruletka', 'Bosch GLM 50-27 CG — yashil lazerli texnologiya tufayli yorug'' joylarda ham nur 4 barobar yaxshi ko''rinadi. Bluetooth orqali smartfonga o''lchovlarni yuborish, IP65 zarbaga chidamli korpus va 1.5 metr balandlikdan tushishga bardosh beradi.', 2100000, 2400000, 13, 'b244b549-7683-0d68-276c-ec76105164a1', 'Bosch', 11, 'BSH-GLM50', 5, 29, 'https://images.unsplash.com/photo-1581094794329-c8112a89af12?q=80&w=800&auto=format&fit=crop', true, false, false, '{"O''lchash masofasi":"0.05 - 50 m","Aniqlik":"±1.5 mm","Nur rangi":"Yashil","Himoya darajasi":"IP65 (suv va changdan to''liq)","Bluetooth":"Mavjud"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('1e89a4e3-1440-569a-9d2a-9413c0a67a99', 'DeWalt DT71569 100 Dona Professional Sverlo va Bitlar To''plami', 'dewalt-dt71569-100-dona-sverlo-toplami', 'Metall, beton, yog''och uchun yuqori sifatli qotishma po''latdan ishlangan sverlolar, magnitli bitlar, golovkalar va mustahkam ToughCase qutisi.', 720000, 850000, 15, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'DeWalt', 40, 'DW-DT71569', 4.9, 38, 'https://images.unsplash.com/photo-1530124566582-a618bc2615dc?q=80&w=800&auto=format&fit=crop', true, false, false, '{"Elementlar soni":"100 dona","Mosligi":"Barcha drel va shurupovyortlar","Quti":"Zarbaga chidamli ToughCase"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('d3077932-428b-1fac-4457-19db1da4a458', 'VERAL Electric 5 metrli o''lchov tasmasi (Ruletka)', 'veral-electric-5m-ruletka', 'VERAL Electric — professional o''lchov ishlari uchun yuqori sifatli 5 metrli ruletka. Lentasining qalinligi 19mm, aniq va yorqin shkalaga ega. Ergonomik kauchuk korpusi sirpanib ketishdan va zarbadan himoya qiladi. Avtomatik qulflanish funksiyasi ishlashni osonlashtiradi.', 20000, 30000, 33, 'b244b549-7683-0d68-276c-ec76105164a1', 'VERAL electric', 50, 'VRL-5M-19', 5, 12, '/products/veral_5m.jpg', true, false, true, '{"O''lchov uzunligi":"5 metr","Tasma kengligi":"19 mm","Material":"ABS plastik + Kauchuk","Korpus xususiyati":"Zarbaga chidamli","Avto-qulflash":"Mavjud"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('04187f9b-d08e-b25e-5b83-d7bbbfe34f8d', 'BIYOTI BYT-2602 Perforator (Rotary Hammer)', 'biyoti-byt-2602-perforator', 'BIYOTI BYT-2602 — uy va yarim professional qurilish ishlari uchun mo''ljallangan kuchli perforator (otboynik). U 3 ta rejimda ishlaydi: burg''ulash, zarbli burg''ulash va o''yish. Komplektda mustahkam plastik keys, qo''shimcha tutqich, chuqurlik o''lchagich, 3 ta SDS-plus pichoq va 2 ta iskana (zubilo) mavjud. Yuqori sifatli Yevropa standarti asosida ishlab chiqarilgan.', 460000, 520000, 11, 'e02986ab-8b78-f9cf-704e-b3796fcf12dc', 'BIYOTI', 25, 'BYT-2602', 4.8, 15, '/products/biyoti_byt2602.png', true, false, true, '{"Ish rejimlari":"3 ta rejim (Teshish, Zarbali teshish, O''yish)","Patron turi":"SDS-Plus","Komplektatsiya":"Keys, 3 ta sverlo, 2 ta zubilo","Standart":"Made for EURO","Quvvat turi":"Tarmoqli (220V)"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('3b16d551-5c26-0d6c-e2c5-196850d64cd2', 'ADEGSO 10289 Kantselyariya/Oboy pichog''i', 'adegso-oboy-pichogi-10289', 'ADEGSO (Model: 10289) — qog''oz, karton, oboy va boshqa materiallarni kesish uchun mo''ljallangan yuqori sifatli ''ustalar tanlovi'' pichog''i. Pichoqning uchini sindirib, doimiy o''tkir holatda ishlatish mumkin (Snap-off blade). Korpusi qulay ushlash uchun maxsus teksturali dizaynga ega.', 10000, 15000, 33, 'd56611a2-145f-66a5-9055-35487ba4d3be', 'ADEGSO', 100, 'ADG-10289', 4.9, 8, '/products/adegso_knife_10289.png', true, false, true, '{"Pichoq turi":"Sindirib yangilanadigan (Snap-off)","Vazifasi":"Oboy, qog''oz, karton kesish","Korpus materiali":"Qattiq plastmassa + rezina qo''shimchalar","Model":"10289"}'::jsonb) ON CONFLICT (id) DO NOTHING;
